from pathlib import Path
import re,json,statistics,hashlib,subprocess,difflib
out=Path(__file__).parent; repo=Path('/home/dagger/dag')
series={}
for l in (out/'benchmark-v1.txt').read_text().splitlines():
 m=re.match(r'BenchmarkParentChainWidth/(\d+)/(general|chain)-\d+\s+(\d+)\s+([\d.]+) ns/op\s+(\d+) B/op\s+(\d+) allocs/op',l)
 if m:
  w,v,n,ns,b,a=m.groups();series.setdefault(w,{}).setdefault(v,[]).append({'iterations':int(n),'ns_per_op':float(ns),'bytes_per_op':int(b),'allocs_per_op':int(a)})
summary=[]
for w,vs in sorted(series.items(),key=lambda p:int(p[0])):
 x={'siblings_per_level':int(w),'levels_with_siblings':4,'samples':vs,'legacy_visited_entries':3+4*int(w),'chain_traversal_lstats':4,'chain_traversal_directory_opens':4,'chain_lazy_info_stats':3,'gate_directory_open_fstatfs_ioctl_close_sequences':3}
 for v,rows in vs.items():x[v]={k:statistics.median(r[k] for r in rows) for k in ('ns_per_op','bytes_per_op','allocs_per_op')}
 x['median_ratio_chain_over_general']=x['chain']['ns_per_op']/x['general']['ns_per_op']; summary.append(x)
(out/'benchmark-summary.json').write_text(json.dumps({'scope':'Synthetic parent-only filter walk; production Linux/ext eligibility gate included; no Dagger command measured','samples_per_variant':5,'sequence':'Go benchmark subtests: all general repetitions then all chain repetitions at each width; not randomized full-command ABBA','rows':summary},indent=2)+'\n')
tests={}
for n in ['unit-v1.jsonl','race-v1.jsonl','baseline-negative.jsonl']:
 rows=[json.loads(l) for l in (out/n).read_text().splitlines() if l.startswith('{')]
 tests[n]={'sha256':hashlib.sha256((out/n).read_bytes()).hexdigest(),'top_level_passed':[r['Test'] for r in rows if r.get('Action')=='pass' and 'Test' in r and '/' not in r['Test']], 'top_level_failed':[r['Test'] for r in rows if r.get('Action')=='fail' and 'Test' in r and '/' not in r['Test']], 'packages':[{'outcome':r['Action'],'elapsed_seconds':r.get('Elapsed')} for r in rows if r['Action'] in ['pass','fail'] and 'Test' not in r]}
(out/'tests-summary.json').write_text(json.dumps(tests,indent=2)+'\n')
patch=''
for n in ['filter.go','parent_chain.go','parent_chain_linux.go','parent_chain_other.go','parent_chain_test.go']:
 dest='internal/fsutil/'+n; old=(repo/dest).read_text() if (repo/dest).exists() else ''
 patch+=''.join(difflib.unified_diff(old.splitlines(True),(out/n).read_text().splitlines(True),fromfile='a/'+dest if old else '/dev/null',tofile='b/'+dest))
(out/'prototype.patch').write_text(patch)
manifest=json.loads((out/'manifest.json').read_text()); manifest['sources']={n:hashlib.sha256((out/n).read_bytes()).hexdigest() for n in ['filter.go','parent_chain.go','parent_chain_linux.go','parent_chain_other.go','parent_chain_test.go']};manifest['status']='isolated prototype; unit/race/scaling benchmark completed; no engine/CLI benchmark or production change';manifest['unit_source_note']='After unit/race, only the benchmark body added an explicit eligibility skip so timings cannot silently exercise fallback. Unit and production source bodies unchanged.'
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
lines=['# Parent synchronization: bounded traversal results','', 'An isolated prototype makes parent-only traversal independent of unrelated siblings. This establishes an algorithmic opportunity; it is not a measured improvement to a Dagger command. No production source was changed.','', '| Unrelated siblings at each of four levels | Existing median | Gated chain median | Allocated bytes/op before → after |','| --- | ---: | ---: | ---: |']
for r in summary:lines.append(f"| {r['siblings_per_level']} | {r['general']['ns_per_op']/1000:.2f} µs | {r['chain']['ns_per_op']/1000:.2f} µs | {r['general']['bytes_per_op']:,.0f} → {r['chain']['bytes_per_op']:,.0f} |")
lines += ['', 'Five repetitions per variant, 250 ms benchmark duration, one Go process, GOMAXPROCS=4, Linux/amd64. The eligible ext-family gate is asserted and included in these timings. Subtests group general then candidate repetitions; they are not randomized paired engine measurements.', '', 'The empty-width case gets slower: the conservative filesystem gate costs more than it saves on an already tiny traversal. At width 1,000 the existing walker visits 4,003 entries; the candidate visits only the root and three selected ancestors. Its traversal performs four explicit lstats and four directory-open checks. Emission also performs three fresh Info stats (and existing metadata/xattr work), and the gate adds three open/fstatfs/ioctl/close sequences. Those are distinct costs: 4+4 is not the total syscall count.', '', 'This test host is unusually wide: the parent separately observed 5,996 entries in /tmp, 332 in /tmp/collections-perf, 86 in /home/dagger, 72 in the benchmark lab and 24 in greetings. The accumulated experiment artifacts can amplify this bottleneck. Do not project the saved CLI sender CPU or these synthetic ratios onto a normal small user checkout.', '', 'Six focused test groups pass normally; those six plus the existing filter regression group pass with the race detector. Tests force the new traversal for semantic parity independently of platform eligibility; the Send protocol test additionally exercises the production gate. They cover ordered stat/data packets, normalization and ignored flags, lazy parent emission, fresh metadata, missing/replaced/symlink paths, cancellation, skip callbacks and read permissions. The baseline-negative test is only an activation/wiring witness: unchanged NewFilterFS does not select the chain implementation. It is not evidence that the legacy behavior is functionally incorrect.', '', 'The generic filter optimization remains held: exact directory-entry spelling requires the Linux/ext/no-casefold gate, and opening a directory does not reproduce I/O faults reported only by enumerating its contents. Those are genuine portability/contract limits. A dedicated internal parent-metadata request is the preferred next prototype: specify fresh literal ancestor lookup under existing filesync authority, preserve a compatible legacy fallback, and avoid silently changing a generic filter contract.', '', 'No snapshots or stats are retained across calls. Actual subtree imports, source invalidation, cache identity and public CLI UX are unchanged by the isolated code. The next proof must run real imports/listing/edits with the explicit request candidate, not infer a full-command saving from this microbenchmark.']
(out/'report.md').write_text('\n'.join(lines)+'\n')
allow=['README.md','report.md','manifest.json','prototype.patch','filter.go','parent_chain.go','parent_chain_linux.go','parent_chain_other.go','parent_chain_test.go','prepare.py','summarize.py','source-overlay.json','overlay.json','baseline-overlay.json','benchmark-v1.txt','benchmark-summary.json','tests-summary.json']
(out/'archive-allowlist.json').write_text(json.dumps({'files':allow,'exclude':'Raw runtime/profiles/auth not captured by this task. JSONL test logs omitted; sanitized outcomes and hashes retained.'},indent=2)+'\n')
print(json.dumps([{'width':r['siblings_per_level'],'base_us':r['general']['ns_per_op']/1000,'chain_us':r['chain']['ns_per_op']/1000,'ratio':r['median_ratio_chain_over_general']} for r in summary]))
